package com.veltronixnexus.nativeengine;
import android.content.Context;import android.media.*;import android.net.Uri;import androidx.annotation.NonNull;import androidx.work.*;import java.io.File;import java.nio.ByteBuffer;import java.util.*;
/** Background codec-preserving copy/remux. It does not apply timeline effects or composite layers. */
public class BackgroundMediaCopyWorker extends Worker{
 public BackgroundMediaCopyWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}
 @NonNull @Override public Result doWork(){String src=getInputData().getString("sourceUri"),name=getInputData().getString("outputName");if(src==null)return Result.failure();MediaExtractor ex=new MediaExtractor();MediaMuxer mux=null;
 try{Uri uri=Uri.parse(src);if("content".equals(uri.getScheme()))ex.setDataSource(getApplicationContext(),uri,null);else ex.setDataSource(uri.getPath());List<Integer> a=new ArrayList<>(),b=new ArrayList<>();File out=new File(getApplicationContext().getExternalFilesDir(null),(name==null?"nexus-export":name)+".mp4");mux=new MediaMuxer(out.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);long duration=0;
 for(int i=0;i<ex.getTrackCount();i++){MediaFormat f=ex.getTrackFormat(i);String m=f.getString(MediaFormat.KEY_MIME);if(m!=null&&(m.startsWith("video/")||m.startsWith("audio/"))){ex.selectTrack(i);a.add(i);b.add(mux.addTrack(f));if(f.containsKey(MediaFormat.KEY_DURATION))duration=Math.max(duration,f.getLong(MediaFormat.KEY_DURATION));}}if(a.isEmpty())return Result.failure();mux.start();ByteBuffer buf=ByteBuffer.allocateDirect(2*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long last=0;
 while(!isStopped()){buf.clear();int n=ex.readSampleData(buf,0);if(n<0)break;int index=a.indexOf(ex.getSampleTrackIndex());if(index>=0){long pts=ex.getSampleTime();info.set(0,n,pts,ex.getSampleFlags());mux.writeSampleData(b.get(index),buf,info);if(duration>0&&pts-last>1000000){setProgressAsync(new Data.Builder().putInt("progress",(int)Math.min(99,pts*100/duration)).build());last=pts;}}if(!ex.advance())break;}
 mux.stop();mux.release();mux=null;ex.release();if(isStopped()){out.delete();return Result.failure();}return Result.success(new Data.Builder().putInt("progress",100).putString("fileUri",Uri.fromFile(out).toString()).build());
 }catch(Exception e){if(mux!=null){try{mux.stop();}catch(Exception ignored){}mux.release();}try{ex.release();}catch(Exception ignored){}return Result.failure(new Data.Builder().putString("error",e.getMessage()).build());}}
}